using System;using System.IO;using System.Collections.Generic;using Bokumyaku.Simulation;
public static class OpeningBaseline {
public static object Run(){var rows=new List<object>();foreach(BuildPreset build in Enum.GetValues(typeof(BuildPreset)))foreach(int seed in new[]{42,73,101}){var meta=new MetaProgress();int bank=0,best=0,first=0;for(int round=1;round<=3;round++){var run=new RunSimulator(seed+round-1,meta);run.SetBuild(build);run.SetWeapon(WeaponKind.Point);while(run.State==RunStatus.Running&&run.TickCount<30000)run.Tick();if(run.State!=RunStatus.Defeated)throw new Exception("Expected bounded defeat");int milestone=run.CompletedWave/5*5;int reward=run.CrystalsReward+Math.Max(0,milestone-best);best=Math.Max(best,milestone);bank+=reward;if(first==0&&bank>=meta.Cost(MetaUpgrade.Damage))first=round;rows.Add(new{build=build.ToString(),seed=run.Seed,round,seconds=run.TickCount/30d,run.CompletedWave,reward,bank,firstPurchaseRound=first,price=meta.Cost(MetaUpgrade.Damage),openingTarget=run.TickCount>=9000&&run.TickCount<=14400,purchaseTarget=first>=2&&first<=3});}}var result=new{source="99070b0",rows,scope="Point weapon, initial meta, 3 seeds x 3 rounds x 3 presets. Manual means no input. No purchases applied. Tick seconds at 1x, not wall-clock. Not first-week progression."};File.WriteAllText(Path.GetFullPath("../docs/evidence/opening-baseline-current.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
